vec4 alphaBlend(vec4 bottom, vec4 top) {
    // Formula for opaque bottom and alpha-premultiplied top
    return vec4(bottom.rgb * (1.0 - top.a) + top.rgb, 1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec4 color = texture(iChannel0, fragCoord / iResolution.xy); // Color is alpha-premultiplied
    fragColor = alphaBlend(vec4(1.0), color);
}

vec2 randomOffset(vec2 coord) {
    float maxValue = 1.5; // Increase to make diffusion faster
    return (texture(iChannel2, coord / iChannelResolution[2].rg).rg * 2.0 - 1.0) * maxValue;
}

vec4 drawCircle(vec4 fragColor, vec2 coord, vec2 center, float radius, vec4 color) {
    radius *= iResolution.x; // Scale radius based on screen resolution
    float alpha = smoothstep(radius + 1.0, radius - 1.0, length(coord - center * iResolution.xy));
    if (alpha == 0.0) {
        return fragColor;
    }
    return vec4(color.rgb * color.a, color.a); // Return alpha-premultiplied color to simplify the averaging
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame == 0) {
        // Draw a circle on a transparent background (alpha premultiplied) on the first frame
        fragColor = vec4(0.0);
        fragColor = drawCircle(fragColor, fragCoord, vec2(0.4, 0.5), 0.1, vec4(0.9, 0.1, 0.1, 1.0));
        fragColor = drawCircle(fragColor, fragCoord, vec2(0.6, 0.5), 0.1, vec4(0.1, 0.1, 0.9, 1.0));
        // Or alternatively, load an image: fragColor = texture(iChannel0, fragCoord / iResolution.xy);
    } else {
        // Diffusion logic for subsequent frames

        // Neighboring pixel positions
        vec2 leftNeighbor = fragCoord + vec2(-1.0, 0.0);
        vec2 rightNeighbor = fragCoord + vec2(1.0, 0.0);
        vec2 topNeighbor = fragCoord + vec2(0.0, 1.0);
        vec2 bottomNeighbor = fragCoord + vec2(0.0, -1.0);

        // Calculate diffusion source positions with random offsets
        vec2 leftDiffusionSource = fragCoord + vec2(-1.0, 0.0) * randomOffset(leftNeighbor);
        vec2 rightDiffusionSource = fragCoord + vec2(1.0, 0.0) * randomOffset(rightNeighbor);
        vec2 topDiffusionSource = fragCoord + vec2(0.0, 1.0) * randomOffset(topNeighbor);
        vec2 bottomDiffusionSource = fragCoord + vec2(0.0, -1.0) * randomOffset(bottomNeighbor);

        // Sample colors from the source positions and calculate their average
        vec4 accumulatedColor = vec4(0.0);
        accumulatedColor += texture(iChannel1, leftDiffusionSource / iResolution.xy);
        accumulatedColor += texture(iChannel1, rightDiffusionSource / iResolution.xy);
        accumulatedColor += texture(iChannel1, topDiffusionSource / iResolution.xy);
        accumulatedColor += texture(iChannel1, bottomDiffusionSource / iResolution.xy);

        accumulatedColor /= 4.0; // Average the sampled colors

        fragColor = accumulatedColor; // Output the blended color
    }
}
